 const lambda=Math.log(model.q)/Math.log(model.p);const top=point(d,d/lambda),origin=point(0,0);shape('path',{d:`M${origin} L${top}`,'stroke':'#d17a82','stroke-dasharray':'6 6',fill:'none'});
 shape('path',{d:path.map(([u,v],i)=>(i?'L':'M')+point(u,v)).join(' '),stroke:'#8be9c9','stroke-width':3,fill:'none',opacity:.85});
