","challenge/engine.js":"/* Exact finite challenge engine. Uses the shipped PerfectPower integer factor counter. */
(function(root){'use strict';
function seedCode(text){let n=2166136261;for(const c of text)n=Math.imul(n^c.charCodeAt(0),16777619)>>>0;return n;}
function problem(spec,seed,mode='score'){
 if(spec.variables.some(v=>!Number.isSafeInteger(Number(v.profit))||Number(v.profit)<0)||spec.variables.reduce((s,v)=>s+Number(v.profit),0)>Number.MAX_SAFE_INTEGER)throw Error('Scores exceed exact browser integer range');
 const code=seedCode(seed),offset=code%39,projects=spec.variables.slice(offset,offset+12),resources=spec.resources.map((r,k)=>({...r,min:0,max:Math.min(r.max,Math.max(Math.max(...projects.map(p=>p.costs[k])),Math.floor(projects.reduce((a,p)=>a+p.costs[k],0)*(38+code%9)/100)))}));
 // A ceiling must fit at least the required project in keep mode.
 if(mode==='keep')resources.forEach((r,k)=>r.max=Math.max(r.max,projects[0].costs[k]));
 if(mode==='lean')resources.forEach((r,k)=>r.max=Math.max(projects[0].costs[k],Math.floor(r.max*85/100)));
 return {schema:'pp-challenge/1',seed,mode,projects,resources,required:mode==='keep'?0:null};
}
function evaluate(p,mask){let score=0,use=Array(5).fill(0);p.projects.forEach((v,j)=>{if(mask&(1<<j)){score+=Number(v.profit);use=use.map((n,k)=>n+v.costs[k]);}});return {mask,score,use,valid:use.every((n,k)=>n<=p.resources[k].max)&&(p.required===null||!!(mask&(1<<p.required)))};}
function solve(p){const rows=Array.from({length:2**p.projects.length},(_,m)=>evaluate(p,m)),masks=p.resources.map((r,k)=>rows.map(x=>x.use[k]<=r.max?1:0));if(p.required!==null)masks.push(rows.map(x=>x.mask&(1<<p.required)?1:0));const count=root.PerfectPowerCounter.countMasks(rows.map(()=>1),masks);let best=-1,bestMasks=[];for(const r of rows)if(r.valid){if(r.score>best){best=r.score;bestMasks=[r.mask];}else if(r.score===best)bestMasks.push(r.mask);}return {count:count.toString(),best,bestMasks,rows};}
const api={problem,evaluate,solve,seedCode};root.PerfectPowerChallenge=api;if(typeof module!=='undefined')module.exports=api;
})(globalThis);
","challenge/index.html":"<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Can you beat the optimizer? Play a daily project puzzle with exact scores, five budgets, hints and reproducible replay links."><meta property="og:title" content="PerfectPower — Can you beat the optimizer?"><meta property="og:description" content="Choose twelve projects. Stay inside five budgets. Discover the exact best choice."><title>Can you beat the optimizer? · PerfectPower</title><link rel="stylesheet" href="/challenge/style.css"></head><body><header><a class="brand" href="/challenge/">PerfectPower <span>PLAY THE POSSIBILITIES</span></a><nav><a href="/geometry/">50-project discovery</a><a href="/portfolio">Explorer & downloads</a></nav></header><main><section class="hero"><div><p class="eyebrow">A DAILY PUZZLE. AN EXACT ANSWER.</p><h1>Can you beat<br>the optimizer?</h1><p>Choose projects that score more together. Keep all five budgets in the green. Then discover the best possible combination.</p><a class="primary button" href="#play">Try the challenge ↓</a><a class="button" href="/geometry/">Explore 702 trillion possibilities</a></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 360 300"><defs><linearGradient id="glow"><stop stop-color="#76edc4"/><stop offset="1" stop-color="#a3a1ff"/></linearGradient></defs><path d="M180 15 320 100 320 205 180 287 40 205 40 100Z M180 15V175 M40 100 180 175 320 100 M180 175V287" fill="none" stroke="url(#glow)" stroke-width="2"/><path d="M85 186 127 161 172 194 218 144 270 112" fill="none" stroke="#fff2b2" stroke-width="5"/><g fill="#76edc4"><circle cx="85" cy="186" r="10"/><circle cx="127" cy="161" r="10"/><circle cx="172" cy="194" r="10"/><circle cx="218" cy="144" r="10"/><circle cx="270" cy="112" r="10"/></g></svg><p>Small choices. Surprising combinations.</p></div></section><section id="play"><div class="play-heading"><div><p class="eyebrow" id="day"></p><h2>Build your best portfolio</h2><p>A portfolio is your chosen group of projects. Tap a card to add or remove it.</p></div><label>Challenge<select id="mode"><option value="score">Highest score</option><option value="keep">Keep the first project</option><option value="lean">Tighter budgets</option></select></label><button id="daily">Today’s puzzle</button></div><div id="notice" role="status" aria-live="polite">Opening the exact challenge…</div><div class="portfolio-strip" id="portfolio-strip" aria-label="Live selection summary"></div><section class="selection-scene"><div><p class="eyebrow">YOUR CHOICES, TAKING SHAPE</p><h3>Build a constellation<br>of projects.</h3><p>Each point is one project. Lit points are your selections. Five rings show how much of each budget you use.</p><span class="scene-status" id="scene-status"></span></div><div id="portfolio-scene"></div></section><div class="game-layout"><section><div id="cards" class="cards"></div></section><aside id="budget-panel"><div class="scorebox"><span>Your score</span><strong id="score">0</strong><p id="personal"></p></div><h3>Your five budgets</h3><div id="budgets"></div><p id="fit" role="status" aria-live="polite"></p><button class="primary" id="reveal">Find what I missed</button><button id="hint">Give me one hint</button><button id="clear">Start over</button><p id="hint-text" aria-live="polite"></p></aside></div><section id="answer" hidden aria-live="polite"></section><div class="share-row"><button id="share">Share this challenge</button><button id="result-card">Save a result card</button><button id="export">Download exact evidence</button><p id="share-status" role="status"></p><input id="share-link" aria-label="Replay link" readonly hidden></div></section><section class="pathways"><article><p class="eyebrow">FOR CURIOUS MINDS</p><h2>Why can two small projects beat one big one?</h2><p>The score alone does not tell you what to pick. A costly project may crowd out a stronger combination. Try a hint, then compare the exact answer with your choice.</p></article><article><p class="eyebrow">FOR TEACHERS & TEAMS</p><h2>A lesson you can play</h2><p>Ask everyone to solve the same replay link. Compare strategies, switch to tighter budgets, then explain the tradeoff. No account or installation is needed to run the puzzle.</p><a href="/research">Explore the mathematics →</a></article></section><details><summary>How the exact answer is calculated</summary><p>This puzzle uses twelve consecutive original Petersen projects, original scores and all five original cost columns. Reproducible puzzle budgets are derived from the seed and differ from the full published problem. PerfectPower’s browser integer factor counter counts the complete feasible population; exhaustive finite optimization finds every best choice. There are 4,096 possible subsets, including the empty subset when no project is required. This browser challenge is tested computation, not a claim that its JavaScript engine is Lean-proved.</p><p>Local progress stays in this browser. Share links contain the puzzle seed, mode and selected project bits; no personal data is included. The geometric artwork above is illustrative.</p><a href="https://github.com/towre676-cloud/perfectpower/blob/main/docs/CHALLENGE_MONOGRAPH.md">Read the mathematical account</a></details><footer><a href="https://our-apps.towre676.chatgpt.site">Our application collection</a> · <a href="/portfolio">Full research Explorer</a> · <a href="/geometry/">The 50-project result</a><p>Exact choices in PerfectPower. Changing systems in DynaComp. Game analysis in NFL PerfectPower. Play in Pokepolis.</p></footer></main><script src="/challenge/counter.js"></script><script src="/challenge/engine.js"></script><script src="/challenge/visuals.js"></script><script src="/challenge/app.js"></script></body></html>
