","challenge/visuals.js":"/* Data-derived SVG graphics. Geometry illustrates costs, not real project subject matter. */
(function(root){'use strict';
const colors=['#6ce8c3','#8cbcff','#c3a1ff','#ffbf88','#ff8faa'];
const fmt=x=>BigInt(x).toLocaleString(),esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function project(v,limits,selected=false){
 const max=Math.max(1,...v.costs),id=Number(v.name.split('_').pop()),prefix='prism-'+id;
 const bars=v.costs.map((cost,k)=>{const x=24+k*26,y=105-k*4,h=Math.round(cost/max*61),top=`${x},${y-h} ${x+13},${y-h-7} ${x+25},${y-h} ${x+12},${y-h+7}`;return `<g><title>Resource ${k+1}: ${cost}, budget ${limits[k].max}</title><path d="M${x} ${y-h}v${h}l12 7v-${h}Z" fill="${colors[k]}" fill-opacity=".36"/><path d="M${x+12} ${y-h+7}v${h}l13 -7v-${h}Z" fill="${colors[k]}" fill-opacity=".65"/><polygon points="${top}" fill="${colors[k]}"/><path d="M${x+12} ${y-h+7}v${h}" stroke="white" stroke-opacity=".25"/></g>`;}).join('');
 return `<svg class="project-art" viewBox="0 0 190 145" aria-hidden="true"><defs><radialGradient id="${prefix}"><stop stop-color="${colors[id%5]}" stop-opacity=".26"/><stop offset="1" stop-color="${colors[id%5]}" stop-opacity="0"/></radialGradient></defs><ellipse cx="95" cy="85" rx="85" ry="60" fill="url(#${prefix})"/><path d="M18 112 94 136 174 108 97 85Z" fill="#102c3b" stroke="${selected?'#a3ffe2':'#507285'}" stroke-opacity=".65"/><path d="M28 114 96 135 162 111 M46 107 114 128 M70 98 138 120" fill="none" stroke="#86adbd" stroke-opacity=".18"/>${bars}<circle cx="95" cy="22" r="${5+id%4}" fill="none" stroke="${colors[id%5]}" stroke-opacity=".5"/><path d="M${70+id%14} 20h10 M150 45h7 M20 52h6" stroke="${colors[id%5]}" stroke-opacity=".35"/></svg>`;
}
function portfolio(p,row){
